const SHA=/^[a-f0-9]{40}$/;
const stable=value=>Array.isArray(value)?value.map(stable):value&&typeof value==="object"?Object.fromEntries(Object.keys(value).sort().map(key=>[key,stable(value[key])])):value;
const hash=value=>createHash("sha256").update(JSON.stringify(stable(value))).digest("hex");
const plannerError=(code,message,issues=[],diagnostics={})=>Object.assign(new Error(message),{code,retryable:false,safeDiagnostics:{validationIssues:[...new Set(issues)].slice(0,20),outputShapeHash:null,...diagnostics}});
const safePath=value=>{const path=String(value||"").trim().replaceAll("\\","/");if(!path||path.length>240||path.startsWith("/")||path.includes(".."))throw plannerError("implementation_plan_invalid","Implementation plan contains an invalid path.",["invalid_path"]);return path;};
const parse=value=>{const raw=String(value||"").trim(),text=/^```(?:json)?\s*[\s\S]*\s*```$/i.test(raw)?raw.replace(/^```(?:json)?\s*/i,"").replace(/\s*```$/,""):raw;try{return{value:JSON.parse(text),shapeHash:hash(text)}}catch{return{issues:["invalid_json"],shapeHash:hash(text)}}};
const discoveredPaths=steps=>{const found=new Set();const visit=value=>{if(typeof value==="string"&&/^[a-z0-9._/-]+$/i.test(value)&&value.includes("/"))found.add(value.replaceAll("\\","/"));else if(Array.isArray(value))value.forEach(visit);else if(value&&typeof value==="object")Object.values(value).forEach(visit);};for(const step of steps.filter(item=>item.status==="completed"&&["inspect_repo","search_code","read_files"].includes(item.stepType)))visit(step.result);return found;};

// Persist references and hashes only. Model prose, source replacements, reasons,
// and arbitrary criterion text never enter durable rejection diagnostics.
function rejectedPlanEvidence(value, {task,candidates,evidence,readStepIds,plannerAttempt,diagnostics}) {
  const pathReference = value => {
    const normalized=typeof value==="string"?value.trim().replaceAll("\\","/"):"";
    return normalized.length<=240&&/^[a-z0-9._/-]+$/i.test(normalized)&&!normalized.startsWith("/")&&!normalized.includes("..")&&!PROTECTED.test(normalized)?normalized:null;
  };
  const requestedMutationPaths=value.files.slice(0,8).map(file=>({path:pathReference(file.path),pathFingerprint:hash(file.path),operation:file.operation}));
  const requestedFocusedTests=value.focusedTests.slice(0,12).map(test=>({path:pathReference(test.path),pathFingerprint:hash(test.path),kind:test.kind}));
  const acceptanceMapping=value.acceptanceMapping.slice(0,30).map(mapping=>({
    criterionIndex:(task.metadata?.selfDevelopment?.acceptanceCriteria||[]).indexOf(mapping.criterion),
    criterionFingerprint:hash(mapping.criterion),
    files:mapping.files.slice(0,8).map(path=>{
      const mutationIndex=value.files.findIndex(file=>file.path===path),focusedTestIndex=value.focusedTests.findIndex(test=>test.path===path);
      return mutationIndex>=0?{mutationIndex}:focusedTestIndex>=0?{focusedTestIndex}:{unmappedPathFingerprint:hash(path)};
    }),
    tests:(mapping.tests||[]).slice(0,12).map(path=>{
      const focusedTestIndex=value.focusedTests.findIndex(test=>test.path===path);
      return focusedTestIndex>=0?{focusedTestIndex}:{unmappedPathFingerprint:hash(path)};
    }),
    omittedFileCount:Math.max(0,mapping.files.length-8),
    omittedTestCount:Math.max(0,(mapping.tests||[]).length-12),
  }));
  return {
    version:1,taskId:task.id,taskStateVersion:task.stateVersion,currentCommit:task.currentCommit,
    continuationGenerationId:task.metadata?.activeContinuation?.generationId||null,plannerAttempt,
    planFingerprint:hash(value),candidatePaths:[...candidates],
    evidenceFingerprint:hash(evidence.map(item=>({path:item.path,contentHash:canonicalContentHash(item.content),readStepId:readStepIds.get(item.path)}))),
    requestedMutationPaths,requestedFocusedTests,acceptanceMapping,
    omittedFocusedTestCount:Math.max(0,value.focusedTests.length-12),omittedMappingCount:Math.max(0,value.acceptanceMapping.length-30),
    validation:{code:diagnostics.rejectionCode||null,classification:diagnostics.classification||null,proposedPath:pathReference(diagnostics.proposedPath)},
    mutationApplied:false,
  };
}

