function schemaIssues(value,reviewRemediation=false){const issues=[];if(!value||typeof value!=="object"||Array.isArray(value))return["top_level_object_required"];const allowed=new Set(Object.keys((reviewRemediation?REVIEW_REMEDIATION_PLAN_SCHEMA:SELF_DEVELOPMENT_IMPLEMENTATION_PLAN_SCHEMA).properties));for(const key of Object.keys(value))if(!allowed.has(key))issues.push(`unknown_top_level:${key}`);if(typeof value.summary!=="string"||!value.summary.trim()||value.summary.length>1000)issues.push("summary_invalid");if(!Array.isArray(value.files)||value.files.length<1||value.files.length>8)issues.push("files_invalid");else value.files.forEach((file,index)=>{if(!file||typeof file!=="object"||Array.isArray(file)){issues.push(`file_${index}_object_required`);return;}const keys=new Set(["path","reason","operation","content","intendedChanges"]);for(const key of Object.keys(file))if(!keys.has(key))issues.push(`file_${index}_unknown:${key}`);if(typeof file.path!=="string")issues.push(`file_${index}_path_invalid`);if(typeof file.reason!=="string"||!file.reason.trim())issues.push(`file_${index}_reason_invalid`);if(!["replace","create"].includes(file.operation))issues.push(`file_${index}_operation_invalid`);if(typeof file.content!=="string"||!file.content.length||file.content.length>250000)issues.push(`file_${index}_content_invalid`);else if(typeof file.path==="string"){const issue=implementationContentIssue(file.path,file.content);if(issue)issues.push(`file_${index}_${issue}`);}if(!Array.isArray(file.intendedChanges)||file.intendedChanges.length>20||file.intendedChanges.some(item=>typeof item!=="string"||!item.trim()||item.length>300))issues.push(`file_${index}_intended_changes_invalid`);});if(!Array.isArray(value.focusedTests)||!value.focusedTests.length||value.focusedTests.some(item=>!item||typeof item!=="object"||typeof item.path!=="string"||!["existing","planned_new"].includes(item.kind)||Object.keys(item).some(key=>!["path","kind"].includes(key))))issues.push("focused_tests_invalid");if(!Array.isArray(value.acceptanceMapping)||!value.acceptanceMapping.length)issues.push("acceptance_mapping_invalid");else value.acceptanceMapping.forEach((item,index)=>{const keys=new Set(["criterion","files","tests"]);if(!item||typeof item!=="object"||Array.isArray(item)||Object.keys(item).some(key=>!keys.has(key))||typeof item.criterion!=="string"||!item.criterion.trim()||!Array.isArray(item.files)||!item.files.length||item.files.some(path=>typeof path!=="string")||!Array.isArray(item.tests)||item.tests.length>12||item.tests.some(path=>typeof path!=="string"))issues.push(`acceptance_mapping_${index}_invalid`);});if(!["low","medium"].includes(value.riskLevel))issues.push("risk_level_invalid");return[...new Set(issues)].slice(0,20);}
const canonicalize=value=>{if(!value||typeof value!=="object"||Array.isArray(value))return value;const result={...value};if(result.acceptanceMapping===undefined&&Array.isArray(result.acceptanceCriteriaMapping))result.acceptanceMapping=result.acceptanceCriteriaMapping;if(result.riskLevel===undefined&&typeof result.risk==="string")result.riskLevel=result.risk;if(result.focusedTests===undefined&&Array.isArray(result.tests))result.focusedTests=result.tests;if(Array.isArray(result.focusedTests))result.focusedTests=result.focusedTests.map(item=>typeof item==="string"?{path:item,kind:"existing"}:item);if(Array.isArray(result.acceptanceMapping)&&Array.isArray(result.files)&&Array.isArray(result.focusedTests)){const mutationPaths=new Set(result.files.map(file=>file?.path).filter(path=>typeof path==="string")),focusedTestPaths=new Set(result.focusedTests.map(test=>test?.path).filter(path=>typeof path==="string"));result.acceptanceMapping=result.acceptanceMapping.map(mapping=>{if(!mapping||typeof mapping!=="object"||Array.isArray(mapping)||!Array.isArray(mapping.files))return mapping;const tests=[...(Array.isArray(mapping.tests)?mapping.tests:[])],files=[];for(const path of mapping.files){if(!mutationPaths.has(path)&&focusedTestPaths.has(path))tests.push(path);else files.push(path);}return{...mapping,files,tests:[...new Set(tests)]};});}delete result.acceptanceCriteriaMapping;delete result.risk;delete result.tests;return result;};

const PLANNER_SYSTEM_CONTEXT="You are Nova's Self-Development implementation planner. Return exactly the requested schema. Every files[].content value is the complete literal replacement file, never instructions, a description, pseudocode, or a patch narrative. Existing files use operation=replace and must be candidateFiles. Extend existing implementations rather than simplifying or replacing unrelated behavior. Preserve unrelated behavior and regression coverage unless an acceptance criterion explicitly requires its removal. A new test may use operation=create only under test/ with complete bounded content; declare it as focusedTests kind=planned_new. Existing focused tests use kind=existing and must be evidence-read or selected from availableEvidenceExpansionTests so they can be read before execution. Each acceptanceMapping.files entry must reference a generated files[].path only. Put focusedTests paths that verify that criterion in acceptanceMapping.tests instead; tests are verification obligations and do not authorize mutation. Never target Voice Mode, ECAPA, ElevenLabs, speaker verification, Voice controls, main, or Production. Never use shell commands or secrets.";
const REVIEW_REMEDIATION_SYSTEM_CONTEXT="You are Nova, the product implementation owner. Return exactly the requested schema for one owner-approved review-remediation plan, not a repair-limit exception. Inspect the current and committed-baseline evidence and structured findings, then decide and implement the product remediation yourself. Every files[].content is a complete literal source replacement, never instructions, pseudocode or a patch narrative. Use operation=replace only for the exact candidateFiles; focusedTests use kind=existing and only the freshly read candidate test paths. acceptanceMapping.files reference generated patch files; acceptanceMapping.tests may reference selected focused tests as verification evidence and never authorize mutation. Every approved review constraint requires meaningful behavioral tests with named literal source excerpts, stimulus and observable code references, and literal assertions; the runtime calculates source hashes. Token-only checks or unwired counters are insufficient. No ninth file, evidence expansion, shell command, secret, retry or new repair extension is permitted. If repair requires broader scope, stop for owner authorization. Preserve unrelated console functionality and existing Voice controls inside the approved scope without modifying Voice Mode behavior, ECAPA, ElevenLabs, speaker verification, Main, Production, or any out-of-scope module. Passing tests do not automatically resolve review findings.";
