  sourceFinding:{source:"structuredReview.findings",meaning:"An unresolved reviewer observation bound to source paths and current evidence; referencing its path does not resolve it."},
  mutationPath:{source:"files[].path",meaning:"A current candidate selected by Nova for an actual complete source replacement. Nova must decide which behavior and files require remediation."},
  focusedTestPath:{source:"focusedTests[].path",meaning:"A freshly read candidate test selected for execution. Selection alone neither modifies the test nor proves that its behavioral assertions are sufficient."},
