    const parsed=parse(generated.message),value=parsed.value,keys=new Set(["status","unrelatedRemovals","intentionalRemovals"]),criteria=new Set(request.acceptanceCriteria||[]),byPath=new Map(comparisons.map(item=>[item.path,item]));
    const validRemoval=(item,intentional)=>item&&typeof item==="object"&&!Array.isArray(item)&&Object.keys(item).every(key=>(intentional?new Set(["path","behavior","baselineExcerpt","criterion"]):new Set(["path","behavior","baselineExcerpt"])).has(key))&&typeof item.path==="string"&&typeof item.behavior==="string"&&item.behavior.trim()&&item.behavior.length<=300&&typeof item.baselineExcerpt==="string"&&item.baselineExcerpt.trim()&&item.baselineExcerpt.length<=2000&&(!intentional||(typeof item.criterion==="string"&&criteria.has(item.criterion)));
    if(parsed.issues||!value||typeof value!=="object"||Array.isArray(value)||Object.keys(value).some(key=>!keys.has(key))||!["preserved","intentional_removal_justified","blocked"].includes(value.status)||!Array.isArray(value.unrelatedRemovals)||value.unrelatedRemovals.length>20||value.unrelatedRemovals.some(item=>!validRemoval(item,false))||!Array.isArray(value.intentionalRemovals)||value.intentionalRemovals.length>20||value.intentionalRemovals.some(item=>!validRemoval(item,true)))throw plannerError("implementation_preservation_unproven","Preservation assessment does not match the bounded semantic schema.",["preservation_assessment_invalid"]);
